//! 📦️ Native boxed output retains real typed backing before its separately funded payload initialization.
use super::{NativeReceive,NativeReceiver,NativeAdvanceSelection,NativeDecodeControl,RetainedCloneRef};
use crate::{OriginalEffectReply,OriginalEffectReplyComplete};
use crate::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneClose,retained_clone_grant_admits}};
use semio_framework_value_native_storage::NativeOwnedStorage;
use std::{mem::ManuallyDrop,marker::PhantomData};
pub struct NativeBoxReceiver<I:crate::owned::tree::NativeValueSource+?Sized,T:NativeReceive<I>>{inner:crate::owned::NativeReceiveSlot<I,T>,pending:ManuallyDrop<Option<T>>,pending_box:ManuallyDrop<Option<Box<T>>>,backing:NativeOwnedStorage<T>,retirement:RetainedCloneClose,closing:bool,marker:PhantomData<fn(&I)>}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native boxed receiver has no funded owner in the required phase")}
fn nested(mut d:RetirementDemand)->Result<RetirementDemand,ValueError>{d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g}}
impl<I:crate::owned::tree::NativeValueSource+?Sized,T:NativeReceive<I>> NativeBoxReceiver<I,T>{pub fn new()->Self{Self{inner:Default::default(),pending:ManuallyDrop::new(None),pending_box:ManuallyDrop::new(None),backing:NativeOwnedStorage::empty(),retirement:Default::default(),closing:false,marker:PhantomData}}}
impl<I:crate::owned::tree::NativeValueSource+?Sized,T:NativeReceive<I>> NativeBoxReceiver<I,T>{
 fn close_dispatch<'reply>(&mut self,original:Option<&mut crate::OriginalRetirementCloseLoan<'_>>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,recover:bool)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{
  if self.terminal_is_empty(){return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}
  let d=self.close_demands(body)?;if !retained_clone_grant_admits(effect.grant(),d)||effect.remaining_work_units()?==0{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}
  if !self.inner.terminal_is_empty(){if !self.inner.is_closing(){return if recover{self.inner.recover_begin_close_into(effect,reply)}else{self.inner.begin_close_into(effect,reply)}}return match(original,recover){(Some(loan),false)=>self.inner.close_original_into(loan,body,effect,reply),(Some(loan),true)=>self.inner.recover_close_original_into(loan,body,effect,reply),(None,false)=>self.inner.close_into(body,effect,reply),(None,true)=>self.inner.recover_close_into(body,effect,reply)}}
  if !self.retirement.is_empty(){return match(original,recover){(Some(loan),false)=>self.retirement.step_original_into(loan,body,effect,reply),(Some(loan),true)=>self.retirement.recover_step_original_into(loan,body,effect,reply),(None,false)=>self.retirement.step_into(body,effect,reply),(None,true)=>self.retirement.recover_step_into(body,effect,reply)}}
  if recover{return Err(invalid())}
  if self.pending_box.is_some(){let turn=self.retirement.begin_granted(&mut self.pending_box,effect);return Ok(reply.complete(turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)))}
  if self.pending.is_some(){let turn=self.retirement.begin_granted(&mut self.pending,effect);return Ok(reply.complete(turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)))}
  if self.backing.initialized(){return Ok(match self.backing.take_box_into(&mut self.pending_box,effect){crate::RetainedWorkPoll::Pending{..}=>reply.pending(),crate::RetainedWorkPoll::Complete(turn)=>reply.complete(turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into))})}
  let turn=self.backing.release(effect);Ok(reply.complete(turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)))
 }
}
impl<I:crate::owned::tree::NativeValueSource+?Sized,T:NativeReceive<I>> NativeReceiver<I,Box<T>> for NativeBoxReceiver<I,T>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing||self.backing.initialized(){return Err(invalid())}if self.pending.is_some(){return Ok(if self.backing.reserved(){NativeOwnedStorage::<T>::move_demand()}else{NativeOwnedStorage::<T>::reserve_demand()})}nested(if self.inner.ready(){self.inner.take_demand()?}else{self.inner.demands(input,body,maximum_work_units)?})}
 fn select_advance(&self,_input:RetainedCloneRef<'_,I>,_body:usize,_maximum_work_units:u64)->Result<NativeAdvanceSelection,ValueError>{if self.closing||self.backing.initialized(){return Err(invalid())}if self.pending.is_some(){return Ok(NativeAdvanceSelection::Local{work:1})}if self.inner.ready(){return Ok(NativeAdvanceSelection::Local{work:self.inner.take_work_demand()?})}Ok(NativeAdvanceSelection::Nested)}
 fn advance_nested(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,witness:semio_framework_value_control_contract::OriginalSourceTurnWitness<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->crate::RetainedWorkPoll<RetainedCloneStep,crate::native_decoding::NativeReceivingFailure>{if self.closing||self.backing.initialized()||self.pending.is_some()||self.inner.ready(){return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(invalid().into()),work:0})}self.inner.advance(input,control,witness,body,maximum_work_units,child(g)).map(|s|RetainedCloneStep::Progress(s.progress()))}
 fn advance_local<'reply>(&mut self,input:RetainedCloneRef<'_,I>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalReceivingPrimary>,ValueError>{
  let result:Result<Option<RetainedCloneStep>,crate::OriginalReceivingPrimary>=(||{let d=self.demands(input,body,effect.maximum_work_units())?;if !retained_clone_grant_admits(effect.grant(),d){return Ok(Some(RetainedCloneStep::Progress(Default::default())))}
   if self.pending.is_some(){if self.backing.reserved(){let turn=self.backing.put_from(&mut self.pending,effect);return turn.result.map(|s|Some(if self.backing.initialized(){RetainedCloneStep::Complete(s.progress())}else{RetainedCloneStep::Progress(s.progress())})).map_err(Into::into)}return match self.backing.reserve_empty(effect){crate::RetainedWorkPoll::Pending{..}=>Ok(None),crate::RetainedWorkPoll::Complete(turn)=>turn.result.map(|s|Some(RetainedCloneStep::Progress(s.progress()))).map_err(Into::into)}}
   if self.inner.ready(){return match self.inner.take(&mut *self.pending,effect){crate::RetainedWorkPoll::Pending{..}=>Ok(None),crate::RetainedWorkPoll::Complete(turn)=>{let step=turn.result?;Ok(Some(RetainedCloneStep::Progress(step.progress())))}}}
   Err(invalid().into())})();
  Ok(match result{Ok(Some(step))=>reply.complete(Ok(step)),Ok(None)=>reply.pending(),Err(error)=>reply.complete(Err(error))})
 }
 fn output_ready(&self)->bool{!self.closing&&self.backing.initialized()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid())}Ok(NativeOwnedStorage::<T>::box_demand())}
 fn take_work_demand(&self)->Result<u64,ValueError>{self.take_demand().map(|_|self.backing.box_work_demand())}
 fn take<'reply>(&mut self,output:&mut Option<Box<T>>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_native_receiver_protocol::OriginalEffectReply<'reply,crate::RetainedCloneStep,crate::OriginalReceivingPrimary>)->Result<semio_framework_value_native_receiver_protocol::OriginalEffectReplyComplete<'reply,crate::RetainedCloneStep,crate::OriginalReceivingPrimary>,crate::ValueError>{let turn=(||->crate::RetainedWorkPoll<RetainedCloneStep,crate::OriginalReceivingPrimary>{if !self.output_ready(){return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(invalid().into()),work:0})}match self.backing.take_box_into(output,effect){crate::RetainedWorkPoll::Pending{work}=>crate::RetainedWorkPoll::Pending{work},crate::RetainedWorkPoll::Complete(turn)=>crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result.map_err(Into::into),work:turn.work})}})();semio_framework_value_native_receiver_protocol::native_record_pure_take(turn,reply)}
 semio_framework_value_native_receiver_protocol::native_receiver_close_start!(closing);
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.inner.terminal_is_empty(){return nested(if self.inner.is_closing(){self.inner.close_demands(body)?}else{self.inner.begin_close_demand()?})}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<T>(false,&None,body)}if self.pending_box.is_some(){return self.retirement.next_owner_demands::<Box<T>>(true,&None,body)}if self.pending.is_some(){return self.retirement.next_owner_demands::<T>(true,&None,body)}if self.backing.initialized(){return Ok(NativeOwnedStorage::<T>::box_demand())}Ok(self.backing.release_demand())}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if self.terminal_is_empty(){return Ok(0)}if !self.inner.terminal_is_empty(){return if self.inner.is_closing(){self.inner.close_work_demand(body)}else{self.inner.begin_close_work_demand()}}if !self.retirement.is_empty(){return self.retirement.next_owner_work::<T>(false,&None,body)}if self.pending_box.is_some(){return self.retirement.next_owner_work::<Box<T>>(true,&None,body)}if self.pending.is_some(){return self.retirement.next_owner_work::<T>(true,&None,body)}Ok(1)}
 fn advance_pending(&self)->bool{false}
 fn close_step<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_dispatch(None,body,effect,reply,false)}
 fn recover_close_step<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_dispatch(None,body,effect,reply,true)}
 fn close_original_step<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_dispatch(Some(original),body,effect,reply,false)}
 fn recover_close_original_step<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{self.close_dispatch(Some(original),body,effect,reply,true)}
 fn requires_original_birth(&self)->bool{if !self.inner.terminal_is_empty(){self.inner.requires_original_birth()}else{self.retirement.requires_original_birth()}}
 fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->crate::OriginalRetirementPoll{if !self.inner.terminal_is_empty(){if grant.maximum_items==0||grant.maximum_depth==0{return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}self.inner.close_original_birth_step(original,child(grant))}else{self.retirement.step_original_birth(original,grant)}}
 fn requires_original_control(&self)->bool{if !self.inner.terminal_is_empty(){self.inner.requires_original_control()}else{self.retirement.requires_original_control()}}
 fn native_terminal_release(&self)->Option<semio_framework_value_native_receiver_protocol::RetainedCursorRelease<Self>>{self.terminal_is_empty().then(||unsafe{semio_framework_value_native_receiver_protocol::RetainedCursorRelease::native(|value:&Self|value.terminal_is_empty())})}
  fn terminal_is_empty(&self)->bool{self.inner.terminal_is_empty()&&self.pending.is_none()&&self.pending_box.is_none()&&self.backing.terminal_is_empty()&&self.retirement.is_empty()}
}
impl<I:crate::owned::tree::NativeValueSource+?Sized,T:NativeReceive<I>> Drop for NativeBoxReceiver<I,T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native boxed receiver retains its actual typed owners");}}
impl<I:crate::owned::tree::NativeValueSource+?Sized,T:NativeReceive<I>> NativeReceive<I> for Box<T>{type Receiver=NativeBoxReceiver<I,T>;fn receiver()->Self::Receiver{NativeBoxReceiver::new()}}
